function findXSum(nums, k, x) {
  // Recount every window from scratch and pick the x most frequent values one at a time.
  const result = [];
  for (let i = 0; i + k <= nums.length; i++) {
    const freq = new Array(51).fill(0);
    for (let j = i; j < i + k; j++) freq[nums[j]]++;
    let total = 0;
    for (let pick = 0; pick < x; pick++) {
      let best = -1;
      // Scanning from 50 down with a strict comparison lets the larger value win ties.
      for (let v = 50; v >= 1; v--) if (freq[v] > 0 && (best === -1 || freq[v] > freq[best])) best = v;
      if (best === -1) break;
      total += best * freq[best];
      freq[best] = 0;
    }
    result.push(total);
  }
  return result;
}

