function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 50 : 1 + Math.floor(rand() * 10);
  // A narrow value range gives repeated values and tied tallies; a wide one gives many distinct values.
  const span = [2, 3, 5, 8, 20, 50][Math.floor(rand() * 6)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  if (!large && rand() < 0.2) nums[0] = 50;
  const k = 1 + Math.floor(rand() * n);
  const x = 1 + Math.floor(rand() * k);
  return [nums, k, x];
}
